// NOTE:
//  import MinHeap from '../utils/heap.min.js'
//
//    const heap = new MinHeap()
//    heap.insert(5)
//    heap.pop()   // returns the smallest value, null when empty

//
//  Chapters:
//    MIN HEAP   The MinHeap class with insert and pop.
//

// ===========================================================================
// ==============================   MIN HEAP   ===============================
// ===========================================================================
//
//   MinHeap   Keeps the smallest value on top, insert and pop in O(log n).
//

// A heap is a binary tree like structure that stores the min value as root node.
// The tree lives in a flat array, each node can be found via:
//      - Parent     = (childIndex - 1) / 2
//      - LeftChild  = parentIndex * 2 + 1
//      - RightChild = parentIndex * 2 + 2
// Insertion:
//      Every new value gets inserted at the bottom, then traversed up to its correct spot.
// Removal:
//      The root is replaced by the last value, which is then traversed down to its correct spot.
export default class MinHeap {
    #values = []

    // Size
    get size()    { return this.#values.length }
    get isEmpty() { return this.size === 0 }

    /**
     * Adds a value to the heap.
     *
     * @param {number} value   (Required) The value to add.
     *
     * @example
     * heap.insert(5)
     */
    insert(value) {
        this.#values.push(value)
        this.#moveUp(this.size - 1)
    }

    /**
     * Removes and returns the smallest value.
     *
     * @returns {number|null} The smallest value, null when the heap is empty.
     *
     * @example
     * const smallest = heap.pop()
     */
    pop() {
        if (this.isEmpty) return null

        const smallest = this.#values[0]
        const last     = this.#values.pop()
        if (this.isEmpty) return smallest

        this.#values[0] = last
        this.#moveDown(0)
        return smallest
    }

    // Get Index
    #getParentIndex(index) { return Math.floor((index - 1) / 2) }
    #getLeftIndex(index)   { return index * 2 + 1 }
    #getRightIndex(index)  { return index * 2 + 2 }

    // Has Node by Index
    #hasParent(index) { return index > 0 }
    #hasLeft(index)   { return this.#getLeftIndex(index) < this.size }
    #hasRight(index)  { return this.#getRightIndex(index) < this.size }

    // Move Values
    #swap(first, second) {
        [this.#values[first], this.#values[second]] = [this.#values[second], this.#values[first]]
    }

    #moveUp(index) {
        while (this.#hasParent(index)) {
            const parentIndex = this.#getParentIndex(index)
            if (this.#values[parentIndex] <= this.#values[index]) return

            this.#swap(parentIndex, index)
            index = parentIndex
        }
    }

    #moveDown(index) {
        while (this.#hasLeft(index)) {
            const leftIndex  = this.#getLeftIndex(index)
            const rightIndex = this.#getRightIndex(index)

            const isRightSmaller = this.#hasRight(index)
                && this.#values[rightIndex] < this.#values[leftIndex]
            const smallerIndex = isRightSmaller ? rightIndex : leftIndex
            if (this.#values[index] <= this.#values[smallerIndex]) return

            this.#swap(index, smallerIndex)
            index = smallerIndex
        }
    }
}
